static VstIntPtr perfHost(AEffect*,VstInt32 op,VstInt32,VstIntPtr,void*,float){return op==audioMasterVersion?2400:0;}
static auto sequence(GrooveDice&p,int slot){std::array<uint32_t,256> out{};auto&bank=GrooveDice::isPerformanceRoll(slot)?p.rollNotes[GrooveDice::rollBank(slot)]:p.notes[slot-4];for(int n=0;n<128;++n){out[n*2]=bank[n].data.load();out[n*2+1]=bank[n].gate.load();}return out;}
static std::vector<uint8_t> legacyState(GrooveDice&p,int count){auto s=p.internalSaveState();std::vector<uint8_t>old(s.begin(),s.begin()+12);for(int n=0;n<4;++n)old[8+n]=uint8_t(count>>(8*n));size_t pos=12;for(int i=0;i<kParamCount;++i){size_t bytes=1+s[pos]+8;if(i<count)old.insert(old.end(),s.begin()+pos,s.begin()+pos+bytes);pos+=bytes;}uint32_t extra=0;for(int n=0;n<4;++n)extra|=uint32_t(s[pos+n])<<(8*n);extra-=GrooveDice::HatPerformanceTrailerSize;if(count<=782)extra-=GrooveDice::PerformanceTrailerSize;for(int n=0;n<4;++n)old.push_back(uint8_t(extra>>(8*n)));old.insert(old.end(),s.begin()+pos+4,s.begin()+pos+4+extra);return old;}
